import { Injectable, computed, inject } from '@angular/core';
import { Claim, Claims, bound, countsAt, isOpen, statusAt } from './claims';
import { People, Person, gradeOn } from './people';
import { Period, Periods } from './periods';
import { NO_RATE, Rates, hundredths, money, rounded } from './rates';
import { Session, addDays } from './session';

/** The statuses claims are counted by, in the order the screen shows them. */
export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'] as const;

/** People's figures added up, leaving out the single highest and the single lowest when there are
 *  three or more. */
function trimmed(figures: bigint[]): bigint {
  const sum = figures.reduce((s, f) => s + f, 0n);
  if (figures.length < 3) return sum;
  const max = figures.reduce((m, f) => (f > m ? f : m));
  const min = figures.reduce((m, f) => (f < m ? f : m));
  return sum - max - min;
}

// The due figures the screen shows, worked out in one place so the people list, the periods list,
// the summary and the header always agree.
@Injectable({ providedIn: 'root' })
export class Figures {
  private readonly claims = inject(Claims);
  private readonly people = inject(People);
  private readonly periods = inject(Periods);
  private readonly rates = inject(Rates);
  private readonly session = inject(Session);

  /** A person's due-total: the sum of their figures, at most the sheet's cap. Null (n/a) is not capped. */
  dueCents(p: Person): bigint | null {
    const sum = this.sumCents(p);
    const cap = this.capCents();
    return sum !== null && cap !== null && sum > cap ? cap : sum;
  }

  /** How far the sum of a person's figures is above the sheet's cap; 0 when it is not (or is n/a). */
  excessCents(p: Person): bigint {
    const sum = this.sumCents(p);
    const cap = this.capCents();
    return sum !== null && cap !== null && sum > cap ? sum - cap : 0n;
  }

  private capCents(): bigint | null {
    const cap = this.session.cap();
    return cap === null ? null : hundredths(cap);
  }

  /** The sum of the figures of a person's claims that count live (not left out by a hold): a settled claim's frozen due, else the
   *  figure their last statement bound it to, else its live due at the rate in force on its date (a
   *  claim with no figure adds nothing). Null when the grade in force on the sheet's today has no rate
   *  there and no claim has a figure. */
  sumCents(p: Person): bigint | null {
    let sum = 0n;
    let keptFigure = false;
    for (const c of this.claims.live().filter((c) => c.personId === p.id)) {
      if (c.settledDue !== null || (bound(c) && c.statedDue !== null)) keptFigure = true;
      // a claim priced at the grade in force on its date keeps a figure too
      else if (!bound(c) && this.rates.inForce(gradeOn(p.grades, c.date), c.date) !== undefined) keptFigure = true;
      sum += this.figureCents(c, p);
    }
    const today = this.session.today();
    const rated = today ? this.rates.inForce(gradeOn(p.grades, today), today) !== undefined : false;
    return rated || keptFigure ? sum : null;
  }

  /** The due of a person's SETTLED claims that count live, at their frozen figures, corrections included. */
  settledCents(p: Person): bigint {
    return this.claims
      .live()
      .filter((c) => c.personId === p.id && c.status === 'SETTLED')
      .reduce((sum, c) => sum + this.figureCents(c, p), 0n);
  }

  /** The due of a person's OPEN and PENDING claims that count live (not held, deferred or retired-and-excluded). */
  openCents(p: Person): bigint {
    return this.claims
      .live()
      .filter((c) => c.personId === p.id && isOpen(c))
      .reduce((sum, c) => sum + this.figureCents(c, p), 0n);
  }

  /** Everyone's settled-total added up (not trimmed). */
  readonly settledTotal = computed(() =>
    money(this.people.people().reduce((sum, p) => sum + this.settledCents(p), 0n)),
  );

  /** Everyone's open-total added up (not trimmed). */
  readonly openTotal = computed(() =>
    money(this.people.people().reduce((sum, p) => sum + this.openCents(p), 0n)),
  );

  /** Everyone's (capped) due-total added up, skipping those whose grade has no rate, trimmed. */
  readonly dueTotal = computed(() =>
    money(trimmed(this.people.people().map((p) => this.dueCents(p)).filter((d): d is bigint => d !== null))),
  );

  /** The due of everyone's overdue claims that count, added up, trimmed. */
  readonly overdueTotal = computed(() =>
    money(trimmed(this.people.people().map((p) => this.overdueCents(p)))),
  );

  /** The signed-in user's own figures: the due-total (n/a when it has none) and overdue-total of the
   *  person whose name or an alias is the user's name, compared as names are (trimmed, ignoring case);
   *  null when no one on the sheet has it. */
  readonly mine = computed(() => {
    const user = this.session.user()?.trim().toLowerCase();
    if (!user) return null;
    const p = this.people
      .people()
      .find((p) => p.name.trim().toLowerCase() === user || p.aliases.some((a) => a.trim().toLowerCase() === user));
    if (!p) return null;
    const due = this.dueCents(p);
    return { dueTotal: due === null ? NO_RATE : money(due), overdueTotal: money(this.overdueCents(p)) };
  });

  /** Each tag ever used on the sheet (on a claim or a person), sorted, with the due of the claims that
   *  count live and carry it, or whose person carries it, once each (a claim with two tags counts in both),
   *  not capped or trimmed. */
  readonly tagTotals = computed(() => {
    const byId = new Map(this.people.people().map((p) => [p.id, p]));
    const used = [...new Set([...this.claims.usedTags(), ...this.people.people().flatMap((p) => p.tags)])].sort();
    const sums = new Map<string, bigint>(used.map((t) => [t, 0n]));
    for (const c of this.claims.live()) {
      const p = byId.get(c.personId);
      if (!p) continue;
      const due = this.figureCents(c, p);
      for (const t of new Set([...c.tags, ...p.tags])) sums.set(t, (sums.get(t) ?? 0n) + due);
    }
    return [...sums].map(([tag, cents]) => ({ tag, dueTotal: money(cents) }));
  });

  /** Each calendar month (yyyy-mm) any claim on the sheet is dated in, in order, with the due of the
   *  claims dated in it that count live, not capped or trimmed. */
  readonly monthTotals = computed(() => {
    const byId = new Map(this.people.people().map((p) => [p.id, p]));
    const months = [...new Set(this.claims.claims().map((c) => c.date.slice(0, 7)))].sort();
    const sums = new Map<string, bigint>(months.map((m) => [m, 0n]));
    for (const c of this.claims.live()) {
      const p = byId.get(c.personId);
      const month = c.date.slice(0, 7);
      if (!p || !sums.has(month)) continue;
      sums.set(month, sums.get(month)! + this.figureCents(c, p));
    }
    return [...sums].map(([month, cents]) => ({ month, dueTotal: money(cents) }));
  });

  /** The number of claims in each status, in the order of STATUSES. */
  readonly statusCounts = computed(() => {
    const claims = this.claims.claims();
    return STATUSES.map((status) => ({ status, count: claims.filter((c) => c.status === status).length }));
  });

  /** A person's claims that count live and are overdue. */
  overdue(p: Person): Claim[] {
    return this.claims.live().filter((c) => c.personId === p.id && this.claims.overdue(c));
  }

  /** The due of a person's overdue claims that count, added up. */
  overdueCents(p: Person): bigint {
    return this.overdue(p).reduce((sum, c) => sum + this.figureCents(c, p), 0n);
  }

  /** The due of a person's OPEN and PENDING claims that count live, split by the claim's age on the
   *  sheet's today (the days from its date): 0 to 30 (a claim dated after today too), 31 to 60, and 61
   *  or more. All 0 with no today. */
  agedCents(p: Person): { upTo30: bigint; upTo60: bigint; over60: bigint } {
    const aged = { upTo30: 0n, upTo60: 0n, over60: 0n };
    const today = this.session.today();
    if (!today) return aged;
    const from30 = addDays(today, -30);
    const from60 = addDays(today, -60);
    for (const c of this.claims.live().filter((c) => c.personId === p.id && isOpen(c))) {
      const due = this.figureCents(c, p);
      if (c.date >= from30) aged.upTo30 += due;
      else if (c.date >= from60) aged.upTo60 += due;
      else aged.over60 += due;
    }
    return aged;
  }

  /** A claim's figure: its settled due, else the figure its person's last statement bound it to (not
   *  while PENDING), else its live due at the rate in force on its date, an overdue claim's late charge on top, at
   *  least the floor;
   *  nothing when it has no figure. */
  figureCents(c: Claim, p: Person): bigint {
    if (c.settledDue !== null) return hundredths(c.settledDue);
    const f = bound(c)
      ? (c.statedDue === null ? null : hundredths(c.statedDue))
      : this.rates.dueCents(hundredths(c.amount), gradeOn(p.grades, c.date), c.date, this.claims.roundingDate(c));
    return f === null ? 0n : this.claims.chargedCents(c, f);
  }

  /** A claim's due as its row shows it: its figure with two decimals, or n/a when it has none. */
  claimDue(c: Claim, p: Person): string {
    if (c.settledDue !== null) return c.settledDue;
    const f = bound(c)
      ? (c.statedDue === null ? null : hundredths(c.statedDue))
      : this.rates.dueCents(hundredths(c.amount), gradeOn(p.grades, c.date), c.date, this.claims.roundingDate(c));
    return f === null ? NO_RATE : money(this.claims.chargedCents(c, f));
  }

  /** What a candidate rate (a percent with up to two decimals) would change if it applied to a grade on
   *  every date: of the OPEN and PENDING claims of people on that grade on the claim's date, not bound
   *  by a statement, how many would show a different due, and the sum of new due minus current due in
   *  cents (a due shown as n/a counting as nothing). Nothing is saved. */
  ratePreview(grade: string, pct: string): { count: number; diffCents: bigint } {
    const people = new Map(this.people.people().map((p) => [p.id, p]));
    const rate = hundredths(pct);
    let count = 0;
    let diffCents = 0n;
    for (const c of this.claims.claims()) {
      const p = people.get(c.personId);
      if (!p || !isOpen(c) || bound(c) || gradeOn(p.grades, c.date) !== grade) continue;
      const roundOn = this.claims.roundingDate(c);
      const now = this.rates.dueCents(hundredths(c.amount), grade, c.date, roundOn);
      const was = now === null ? null : this.claims.chargedCents(c, now);
      const will = this.claims.chargedCents(c, rounded(hundredths(c.amount) * rate, 10000n, this.session.roundsHalfUp(roundOn)));
      if (was === will) continue;
      count++;
      diffCents += will - (was ?? 0n);
    }
    return { count, diffCents };
  }

  /** Whether a person is active: they have an OPEN or PENDING claim that counts live dated within the
   *  30 days up to and including the sheet's today. */
  active(p: Person): boolean {
    const today = this.session.today();
    if (!today) return false;
    const from = addDays(today, -29);
    return this.claims.live().some((c) => c.personId === p.id && isOpen(c) && c.date >= from && c.date <= today);
  }

  /** A person's settled figure: the frozen dues of their SETTLED claims dated within the 90 days up to
   *  and including the sheet's today, added up; 0 with none. */
  recentSettledCents(p: Person): bigint {
    const today = this.session.today();
    if (!today) return 0n;
    const from = addDays(today, -89);
    return this.claims
      .claims()
      .filter((c) => c.personId === p.id && c.status === 'SETTLED' && c.settledDue !== null && c.date >= from && c.date <= today)
      .reduce((sum, c) => sum + hundredths(c.settledDue as string), 0n);
  }

  /** The grade in force on the sheet's today, the one the list shows. */
  gradeToday(p: Person): string {
    const today = this.session.today();
    return today ? gradeOn(p.grades, today) : p.grade;
  }

  /** Each period's live due-total for each person, in cents, by period id then person id: the figures
   *  of the person's claims whose due-by falls in it and that counted by the status they had at the end of
   *  the period's last day, as their status log records it (one added after then does not count), and
   *  that are not left out now by a hold or a deferral — each its due as shown now: a settled claim's
   *  frozen due, else as its person's last statement bound it, else its live due, an overdue claim's
   *  late charge on top (a claim with no figure adds nothing). */
  private readonly livePersonPeriodCents = computed(() => {
    const grades = new Map(this.people.people().map((p) => [p.id, p.grades]));
    const sums = new Map<number, Map<number, bigint>>();
    for (const c of this.claims.periodCandidates()) {
      const period = this.periods.of(c.dueBy);
      if (!period || !countsAt(statusAt(c, period.to))) continue;
      let due: bigint | null;
      if (c.settledDue !== null) due = hundredths(c.settledDue);
      else if (bound(c)) due = c.statedDue === null ? null : hundredths(c.statedDue);
      else {
        const grade = grades.get(c.personId);
        due = grade === undefined ? null : this.rates.dueCents(hundredths(c.amount), gradeOn(grade, c.date), c.date, this.claims.roundingDate(c));
      }
      if (due !== null && c.settledDue === null) due = this.claims.chargedCents(c, due);
      const byPerson = sums.get(period.id) ?? new Map<number, bigint>();
      byPerson.set(c.personId, (byPerson.get(c.personId) ?? 0n) + (due ?? 0n));
      sums.set(period.id, byPerson);
    }
    return sums;
  });

  /** A person's due-total for a period: fixed when it was closed or soft-closed (0.00 for a person added since), else
   *  live. */
  personPeriodDue(period: Period, personId: number): string {
    if (period.closed || period.soft) return period.closedPersonTotals?.[personId] ?? '0.00';
    return money(this.livePersonPeriodCents().get(period.id)?.get(personId) ?? 0n);
  }

  /** Each open period's live due-total, by period id: the sum of the people's live figures for it. */
  readonly periodDueTotals = computed(() => {
    const totals = new Map<number, string>();
    for (const [id, byPerson] of this.livePersonPeriodCents()) {
      totals.set(id, money([...byPerson.values()].reduce((sum, d) => sum + d, 0n)));
    }
    return totals;
  });
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.EntityListeners;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.history.History;

/** A claim by a person on a sheet: an amount (two decimals), a date, a note, a status and, once opened,
 *  a number and who opened it. A negative amount is a correction, naming the number of the claim it corrects. */
@Entity
@EntityListeners(History.class)
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    /** Its place in the sheet's list, newest (highest) first: set when added, and again when reassigned. */
    @Column(name = "list_order", nullable = false)
    private long listOrder;

    @Column(name = "amount", nullable = false)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    /** The day it is due by: fixed when it is added, from the terms of its person's grade in force on its
     *  date then, counted as that many business days after its date (skipping weekends and the sheet's
     *  holidays listed then); it does not follow later changes to the terms or its date. Adding a holiday
     *  works it out again, with the same terms, while the claim is not SETTLED or VOID. */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    /** The terms its due-by was fixed with: that many business days after its date. */
    @Column(name = "terms", nullable = false)
    private int terms;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** A correction's: the number of the SETTLED claim of the same person it corrects; none otherwise. */
    @Column(name = "corrects_number")
    private String corrects;

    /** Given when the claim is opened; none while a draft or once voided. */
    @Column(name = "claim_number")
    private String number;

    /** Fixed when the claim is settled, if its grade had a rate then; none otherwise. */
    @Column(name = "settled_due")
    private BigDecimal settledDue;

    /** The user who opened the claim; none while a draft. */
    @Column(name = "opened_by")
    private String openedBy;

    /** The user who last edited the claim; none while never edited. */
    @Column(name = "edited_by")
    private String editedBy;

    /** Bound by its person's last statement, which counted it: it shows and totals its stated due. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The figure it had when its person's last statement bound it; none when that was n/a, or unbound. */
    @Column(name = "stated_due")
    private BigDecimal statedDue;

    /** The date an OPEN claim is deferred until; none when never deferred. */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** How many proofs it has: raised by one at a time. */
    @Column(name = "proofs", nullable = false)
    private int proofs;

    /** The number of the claim it was split from; none when it was not split off another. */
    @Column(name = "split_from")
    private String splitFrom;

    /** The number of the bulk settle batch that settled it; none when settled one at a time, or never. */
    @Column(name = "settle_batch")
    private Integer settleBatch;

    /** The user whose editor is open on it, locking it for every other user; none while unlocked. */
    @Column(name = "locked_by")
    private String lockedBy;

    /** Whether it was added (or split off) while its period, the one containing its due-by, was soft-closed. */
    @Column(name = "late_entry", nullable = false)
    private boolean lateEntry;

    /** The last day (the sheet's today then) a reminder was written for it; none when never reminded. */
    @Column(name = "reminded_on")
    private LocalDate remindedOn;

    /** Its external reference, unique on its sheet without regard to case; none when not given. */
    @Column(name = "ref")
    private String ref;

    /** The reason it was voided with, from the sheet's list; none when not voided, or voided without one. */
    @Column(name = "void_reason")
    private String voidReason;

    /** Its tags, sorted and comma separated; none when it carries none. */
    @Column(name = "tags")
    private String tags;

    /** Its status log: one line per status it has had, oldest first. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_status_log", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "seq")
    private List<StatusChange> statusLog = new ArrayList<>();

    /** Its comments, in the order written. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_comment", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "seq")
    private List<ClaimComment> comments = new ArrayList<>();

    /** Its lines, in the order added; while it has any, its amount is what they add up to. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_line", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "seq")
    private List<ClaimLine> lines = new ArrayList<>();

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, LocalDate dueBy, String note,
            String corrects) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.dueBy = dueBy;
        this.note = note;
        this.corrects = corrects;
    }

    /** A copy of the claim for a person on another sheet, listed at a place there: its status, dates, note,
     *  terms, frozen figure, tags, status log, comments and lines carried; no number (one is given there), no figure
     *  a statement bound, no reference, settle batch or lock. */
    public Claim copyTo(String otherSheetId, Long otherPersonId, long otherListOrder) {
        Claim copy = new Claim(otherSheetId, otherPersonId, amount, date, dueBy, note, corrects);
        copy.listOrder = otherListOrder;
        copy.terms = terms;
        copy.status = status;
        copy.settledDue = settledDue;
        copy.stated = stated;
        copy.statedDue = statedDue;
        copy.openedBy = openedBy;
        copy.editedBy = editedBy;
        copy.deferredUntil = deferredUntil;
        copy.proofs = proofs;
        copy.splitFrom = splitFrom;
        copy.lateEntry = lateEntry;
        copy.remindedOn = remindedOn;
        copy.voidReason = voidReason;
        copy.tags = tags;
        statusLog.forEach(l -> copy.statusLog.add(new StatusChange(l.getStatus(), l.getBy(), l.getOn(), l.getDue())));
        comments.forEach(c -> copy.comments.add(new ClaimComment(c.getBy(), c.getOn(), c.getText())));
        lines.forEach(l -> copy.lines.add(new ClaimLine(l.getLabel(), l.getQty(), l.getUnit())));
        return copy;
    }

    /** The sheet's today when it was first opened, from its status log; none when never logged as opened. */
    public LocalDate openedOn() {
        return statusLog.stream().filter(l -> l.getStatus() == ClaimStatus.OPEN).map(StatusChange::getOn)
                .findFirst().orElse(null);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    /** Move the claim to another person on the sheet. */
    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public long getListOrder() {
        return listOrder;
    }

    public void setListOrder(long listOrder) {
        this.listOrder = listOrder;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public String getCorrects() {
        return corrects;
    }

    public void setCorrects(String corrects) {
        this.corrects = corrects;
    }

    /** A correction: its amount is negative. Its due has no floor and no late charge. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public LocalDate getDueBy() {
        return dueBy;
    }

    public void setDueBy(LocalDate dueBy) {
        this.dueBy = dueBy;
    }

    public int getTerms() {
        return terms;
    }

    public void setTerms(int terms) {
        this.terms = terms;
    }

    public String getRef() {
        return ref;
    }

    public void setRef(String ref) {
        this.ref = ref;
    }

    public String getVoidReason() {
        return voidReason;
    }

    public void setVoidReason(String voidReason) {
        this.voidReason = voidReason;
    }

    /** Its tags, sorted; empty when it carries none. */
    public List<String> getTags() {
        return tags == null ? List.of() : List.of(tags.split(","));
    }

    /** Carry the tags (normalised: trimmed, lower-cased, without repeats and sorted). */
    public void setTags(List<String> tags) {
        this.tags = tags.isEmpty() ? null : String.join(",", tags);
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public String getEditedBy() {
        return editedBy;
    }

    public void setEditedBy(String editedBy) {
        this.editedBy = editedBy;
    }

    public boolean isStated() {
        return stated;
    }

    /** Bound by its person's last statement now: stated, and not PENDING (a PENDING claim shows and totals
     *  its live figure; rejected back to OPEN, it is bound again). */
    public boolean isBound() {
        return stated && status != ClaimStatus.PENDING;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    /** Bind the claim to a figure (none for n/a), or unbind it. */
    public void setStated(boolean stated, BigDecimal statedDue) {
        this.stated = stated;
        this.statedDue = stated ? statedDue : null;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    public void setDeferredUntil(LocalDate deferredUntil) {
        this.deferredUntil = deferredUntil;
    }

    /** Deferred on a day: OPEN, with a deferred-until date after it. From that date on it is an OPEN claim
     *  like any other. */
    public boolean deferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }

    public int getProofs() {
        return proofs;
    }

    /** Raise its proofs count by one. */
    public void addProof() {
        proofs++;
    }

    public String getSplitFrom() {
        return splitFrom;
    }

    public void setSplitFrom(String splitFrom) {
        this.splitFrom = splitFrom;
    }

    public Integer getSettleBatch() {
        return settleBatch;
    }

    public void setSettleBatch(Integer settleBatch) {
        this.settleBatch = settleBatch;
    }

    public String getLockedBy() {
        return lockedBy;
    }

    public void setLockedBy(String lockedBy) {
        this.lockedBy = lockedBy;
    }

    public boolean isLateEntry() {
        return lateEntry;
    }

    public void setLateEntry(boolean lateEntry) {
        this.lateEntry = lateEntry;
    }

    public LocalDate getRemindedOn() {
        return remindedOn;
    }

    public void setRemindedOn(LocalDate remindedOn) {
        this.remindedOn = remindedOn;
    }

    public List<StatusChange> getStatusLog() {
        return List.copyOf(statusLog);
    }

    /** Add a line to its status log, for the status it has now. */
    public void logStatus(String by, LocalDate on, BigDecimal due) {
        statusLog.add(new StatusChange(status, by, on, due));
    }

    public List<ClaimComment> getComments() {
        return List.copyOf(comments);
    }

    /** Add a comment after those it has. */
    public void addComment(String by, LocalDate on, String text) {
        comments.add(new ClaimComment(by, on, text));
    }

    public List<ClaimLine> getLines() {
        return List.copyOf(lines);
    }

    /** Add a line after those it has; its amount becomes what its lines add up to. */
    public void addLine(String label, int qty, BigDecimal unit) {
        lines.add(new ClaimLine(label, qty, unit));
        amount = lines.stream().map(ClaimLine::total).reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
    }
}

import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { People, Person, gradeOn, heldOn, retiredBy } from './people';
import { hundredths, rounded } from './rates';
import { Session, addDays, daysBetween, isDate } from './session';

export interface Claim {
  id: number;
  personId: number;
  /** Two decimals, as the server stores it. */
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  /** Given when opened: the next on the sheet in its fiscal year (FY2026-1, FY2026-2, ...), or while numbering by period the next in its
   *  period (<period name>-1, ...) or in no period (X-1, ...); null while a draft. */
  number: string | null;
  /** The due fixed when it was settled, two decimals; null while its due is live (not settled, or
   *  settled while its grade had no rate). */
  settledDue: string | null;
  /** The user who opened it; null while a draft. That user cannot settle it. */
  openedBy: string | null;
  /** Bound by its person's last statement, which counted it: it shows and totals `statedDue` (not while
   *  PENDING, see `bound`). */
  stated: boolean;
  /** The figure the last statement bound, two decimals; null while unbound, or when that was n/a. */
  statedDue: string | null;
  /** The date it is due by (YYYY-MM-DD): fixed when it was added, its date plus the terms of its person's
   *  grade in force on its date then (the sheet's terms when the grade has none of its own). */
  dueBy: string;
  /** A correction's (a negative amount): the number of the SETTLED claim of the same person it
   *  corrects; null otherwise. */
  corrects: string | null;
  /** Its status log: one line per status it has had, oldest first. */
  statusLog: StatusLine[];
  /** The date it was deferred until (YYYY-MM-DD); null when never deferred. It is deferred only while
   *  OPEN and the sheet's today is before it (see `Claims.deferred`). */
  deferredUntil: string | null;
  /** How many proofs it has. One whose due is above the proof threshold in force on its date cannot be
   *  settled or approved with none. */
  proofs: number;
  /** The number of the claim it was split from; null when it was not split off another. */
  splitFrom: string | null;
  /** The user whose editor is open on it, locking it for every other user until they save or cancel it,
   *  or the sheet's today changes; null while unlocked. */
  lockedBy: string | null;
  /** Whether it was added while its period was soft-closed. */
  lateEntry: boolean;
  /** The last day (YYYY-MM-DD) a reminder was written for it; null when never reminded. */
  remindedOn: string | null;
  /** Its external reference, unique on the sheet without regard to case; null when not given. */
  ref: string | null;
  /** Its tags: trimmed, lower-cased, without repeats, sorted; empty when it carries none. */
  tags: string[];
  /** The reason it was voided with, from the sheet's list; null when not voided, or voided without one. */
  voidReason: string | null;
  /** Its comments, in the order written. */
  comments: CommentLine[];
  /** The number of the bulk settle batch that settled it; null when settled one at a time, or never. */
  settleBatch: number | null;
  /** Its lines, in the order added; while it has any, its amount is what they add up to. */
  lines: ClaimLine[];
}

/** A line of a claim: its label, a whole quantity of at least 1 and a unit amount, two decimals. */
export interface ClaimLine {
  label: string;
  qty: number;
  unit: string;
}

/** A comment on a claim: who wrote it, the sheet's today then (YYYY-MM-DD), and its text. */
export interface CommentLine {
  by: string;
  on: string;
  text: string;
}

/** A line of a claim's status log: the status it took, who changed it, the sheet's today then
 *  (YYYY-MM-DD), and the due it had then, two decimals (null when n/a). */
export interface StatusLine {
  status: ClaimStatus;
  by: string;
  on: string;
  due: string | null;
}

/** DRAFT when added; DRAFT -> OPEN -> SETTLED, and DRAFT, OPEN or PENDING -> VOID. A clerk settling a
 *  due above the clerk limit makes it PENDING: a steward approves it (SETTLED) or rejects it (OPEN). A
 *  steward can re-settle a SETTLED claim at its figure today. A DRAFT can be deleted (DELETED, counting
 *  nowhere) and restored to DRAFT on the sheet's today it was deleted. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED';

/** A status change a claim's buttons ask for. */
export type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject' | 'resettle' | 'delete' | 'restore';

/** Whether a claim in this status counts toward claimed, due-total and every total. */
export function counts(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING' || c.status === 'SETTLED';
}

/** Whether a claim in this status counts toward the totals; no status (not yet added) does not. */
export function countsAt(status: ClaimStatus | null): boolean {
  return status === 'OPEN' || status === 'PENDING' || status === 'SETTLED';
}

/** The status a claim had at the end of a day (YYYY-MM-DD), as its status log records it: its latest line
 *  dated on or before it; null when it was added after it. A claim with no log has its status now. */
export function statusAt(c: Claim, day: string): ClaimStatus | null {
  if (c.statusLog.length === 0) return c.status;
  let status: ClaimStatus | null = null;
  for (const l of c.statusLog) if (l.on <= day) status = l.status;
  return status;
}

/** Whether a claim is still open (OPEN or PENDING): it goes overdue, and a hold over its date takes it
 *  out of the live totals unless a statement binds it. */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** Whether a claim is bound by its person's last statement now: a PENDING claim shows and totals its
 *  live figure until rejected back to OPEN. */
export function bound(c: Claim): boolean {
  return c.stated && c.status !== 'PENDING';
}

export interface ClaimFields {
  amount: string;
  /** Blank takes the sheet's today. */
  date: string;
  note: string;
  /** The number of the settled claim a negative amount corrects; blank for any other claim. */
  corrects: string;
  /** The external reference, surrounding spaces removed; blank for none. */
  ref: string;
  /** The tags, comma separated; blank for none. */
  tags: string;
}

// The people's claims on the active sheet, newest first, re-read from the server each time the
// sheet is loaded. Sums are kept in whole cents so they add up exactly, and count only OPEN, PENDING
// and SETTLED claims.
@Injectable({ providedIn: 'root' })
export class Claims {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);
  private readonly people = inject(People);

  readonly claims = signal<Claim[]>([]);
  /** The tags the sheet's claims have carried, as last read from the server. */
  private readonly storedTags = signal<string[]>([]);
  /** Every tag ever used on the sheet, sorted: those stored and those its claims carry now. */
  readonly usedTags = computed(() =>
    [...new Set([...this.storedTags(), ...this.claims().flatMap((c) => c.tags)])].sort(),
  );
  /** The ids of the claims chosen for a bulk action. */
  readonly selected = signal<ReadonlySet<number>>(new Set());
  private loads = 0;

  /** The claims that count in the live totals: those that count, less the OPEN and PENDING claims bound
   *  by no statement and dated within one of their person's holds or whose person's retirement date is
   *  reached, and the deferred claims. */
  readonly live = computed(() => {
    const leftOut = this.leftOut();
    return this.claims().filter((c) => counts(c) && !leftOut(c) && !this.deferred(c));
  });

  /** The claims a period's figures may count, whatever their status: all but the OPEN and PENDING claims
   *  bound by no statement and dated within one of their person's holds, and the deferred claims, as the
   *  live totals leave those out. */
  readonly periodCandidates = computed(() => {
    const leftOut = this.leftOut();
    return this.claims().filter((c) => !leftOut(c) && !this.deferred(c));
  });

  /** Whether a hold or a retirement leaves a claim out of the live totals: it is OPEN or PENDING, bound
   *  by no statement, and dated within one of its person's holds or its person's retirement date is
   *  reached on the sheet's today. */
  private readonly leftOut = computed(() => {
    const today = this.session.today();
    const byId = new Map(this.people.people().map((p) => [p.id, p]));
    return (c: Claim): boolean => {
      const p = byId.get(c.personId);
      return isOpen(c) && !bound(c) && p !== undefined
        && (heldOn(p.holds, c.date) || retiredBy(p, today));
    };
  });

  /** The claims that count toward claimed: the live ones, leaving out claims that correct another. */
  private readonly counted = computed(() => this.live().filter((c) => !c.corrects));

  /** Each person's claimed, in cents, by person id. */
  readonly claimedCents = computed(() => {
    const out = new Map<number, number>();
    for (const c of this.counted()) out.set(c.personId, (out.get(c.personId) ?? 0) + cents(c.amount));
    return out;
  });

  /** Everyone's claimed added up, with two decimals. */
  readonly total = computed(() => money(this.counted().reduce((sum, c) => sum + cents(c.amount), 0)));

  /** The date a claim is due by: fixed when it was added, from the terms of its person's grade then. */
  dueBy(c: Claim): string {
    return c.dueBy;
  }

  /** The date a claim's lateness runs from: its due-by plus the grace days in force on its date of its
   *  person's grade in force then (none: the due-by). */
  lateFrom(c: Claim): string {
    const p = this.people.people().find((x) => x.id === c.personId);
    const grace = p === undefined ? 0 : this.session.graceOn(gradeOn(p.grades, c.date), c.date);
    return grace === 0 ? this.dueBy(c) : addDays(this.dueBy(c), grace);
  }

  /** Whether a claim is overdue: OPEN or PENDING, not deferred, with its due-by plus its grace (see
   *  lateFrom) before the sheet's today. */
  overdue(c: Claim): boolean {
    const today = this.session.today();
    return isOpen(c) && !this.deferred(c) && today !== null && this.lateFrom(c) < today;
  }

  /** Whether a claim shows as deferred: its deferred-until date is after the sheet's today, whatever its
   *  status (a deferred claim voided keeps showing it). Only an OPEN one is left out of totals (`deferred`). */
  deferredShown(c: Claim): boolean {
    const today = this.session.today();
    return c.deferredUntil !== null && today !== null && today < c.deferredUntil;
  }

  /** Whether a claim is deferred: OPEN, with a deferred-until date after the sheet's today. Until then it
   *  counts in no total, is not overdue and cannot be settled. */
  deferred(c: Claim): boolean {
    const today = this.session.today();
    return c.status === 'OPEN' && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
  }

  /** The late charge, in cents, on a claim's figure (in cents): while it is overdue, for each full 30 days
   *  past its due-by plus its grace (see lateFrom), the sheet's late percent in force on that boundary date
   *  (that date plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries before it, rounded to cents as its date rounds, the charges added up; none otherwise, and none
   *  on a correction. Never bound by a statement; frozen into the due when settled. */
  lateCents(c: Claim, figureCents: bigint): bigint {
    const today = this.session.today();
    if (!this.overdue(c) || today === null || c.amount.startsWith('-')) return 0n;
    const from = this.lateFrom(c);
    const periods = Math.floor(daysBetween(from, today) / 30);
    const halfUp = this.session.roundsHalfUp(c.date);
    let total = 0n;
    for (let k = 1; k <= periods; k++) {
      total += rounded((figureCents + total) * hundredths(this.session.latePctOn(addDays(from, 30 * k))), 10000n, halfUp);
    }
    return total;
  }

  /** A claim's due from its figure (the rate figure, or the one its statement bound), in cents: the figure
   *  with its late charge on top, at least the sheet's floor in force on the claim's date (the floor applied
   *  last); a correction takes neither charge nor floor. */
  chargedCents(c: Claim, figureCents: bigint): bigint {
    if (c.amount.startsWith('-')) return figureCents;
    const due = figureCents + this.lateCents(c, figureCents);
    const floor = hundredths(this.session.floorOn(c.date));
    return due < floor ? floor : due;
  }

  /** The date a claim's figures round by: its own, or for a correction the date of the claim of the same
   *  person it corrects (its own when that is not found). */
  roundingDate(c: Claim): string {
    if (c.corrects === null) return c.date;
    return this.claims().find((o) => o.personId === c.personId && o.number === c.corrects)?.date ?? c.date;
  }

  /** A person's claims, newest first. */
  of(personId: number): Claim[] {
    return this.claims().filter((c) => c.personId === personId);
  }

  /** A person's claimed, with two decimals. */
  claimed(personId: number): string {
    return money(this.claimedCents().get(personId) ?? 0);
  }

  /** Replace a person's claims with these, as the server answered them (newest first). */
  replaceOf(personId: number, theirs: Claim[]): void {
    const byId = new Map(theirs.map((c) => [c.id, c]));
    this.claims.update((cs) => cs.map((c) => (c.personId === personId ? (byId.get(c.id) ?? c) : c)));
  }

  /** Re-read the active sheet's claims from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.claims.set([]);
    this.storedTags.set([]);
    this.selected.set(new Set());
    if (!user || !sid) return null;
    try {
      const [claims, tags] = await Promise.all([
        firstValueFrom(this.http.get<Claim[]>(`${this.url(sid)}/claims`, { headers: { 'X-User': user } })),
        firstValueFrom(this.http.get<string[]>(`${this.url(sid)}/claim-tags`, { headers: { 'X-User': user } })),
      ]);
      if (load === this.loads) {
        this.claims.set(claims);
        this.storedTags.set(tags);
      }
      return null;
    } catch (e) {
      return failed('load', e).replace(' claim', ' claims');
    }
  }

  /** Add a claim for a person; an error message when refused. */
  async add(personId: number, f: ClaimFields): Promise<string | null> {
    const refused = this.check(f);
    if (refused) return refused;
    const sid = this.session.sheetId()!;
    try {
      const claim = await firstValueFrom(
        this.http.post<Claim>(`${this.url(sid)}/people/${personId}/claims`, this.body(f), {
          headers: { 'X-User': this.session.user()! },
        }),
      );
      if (this.session.sheetId() === sid) this.claims.update((cs) => [claim, ...cs]);
      return null;
    } catch (e) {
      return failed('add', e);
    }
  }

  /** Add a DRAFT claim for a person with the named template's amount and note as they are now, dated as a
   *  claim added with no date; an error message when refused. */
  async addFromTemplate(personId: number, template: string): Promise<string | null> {
    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
    if (!template) return 'Choose a claim template.';
    const sid = this.session.sheetId()!;
    try {
      const claim = await firstValueFrom(
        this.http.post<Claim>(`${this.url(sid)}/people/${personId}/template-claims`, { template }, {
          headers: { 'X-User': this.session.user()! },
        }),
      );
      if (this.session.sheetId() === sid) this.claims.update((cs) => [claim, ...cs]);
      return null;
    } catch (e) {
      return failed('add', e);
    }
  }

  /** Quick-add a DRAFT claim dated the sheet's today, with an empty note, for the person with the
   *  name, the server adding them with grade A first when the sheet has no one by it; an error
   *  message when refused. */
  async quickAdd(name: string, amount: string): Promise<string | null> {
    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
    if (!name.trim()) return 'Enter a name.';
    const refused = this.check({ amount, date: '', note: '', corrects: '', ref: '', tags: '' });
    if (refused) return refused;
    const sid = this.session.sheetId()!;
    try {
      const added = await firstValueFrom(
        this.http.post<{ person: Person; personAdded: boolean; claim: Claim }>(
          `${this.url(sid)}/quick-claims`,
          { name: name.trim(), amount: amount.trim() },
          { headers: { 'X-User': this.session.user()! } },
        ),
      );
      if (this.session.sheetId() === sid) {
        this.people.people.update((ps) =>
          ps.some((p) => p.id === added.person.id)
            ? ps.map((p) => (p.id === added.person.id ? added.person : p))
            : [...ps, added.person],
        );
        this.claims.update((cs) => [added.claim, ...cs]);
      }
      return null;
    } catch (e) {
      return failed('add', e);
    }
  }

  /** Add a DRAFT claim for each pasted line of name,amount,date,note, in order, for the person on the
   *  sheet with the name; how many were added, or an error message when any line is refused (then the
   *  server adds none). */
  async paste(text: string): Promise<number | string> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    if (!text.trim()) return 'Paste at least one line of name,amount,date,note.';
    try {
      const done = await firstValueFrom(
        this.http.post<{ added: number; claims: Claim[] }>(
          `${this.url(sid)}/claims/paste`,
          { text },
          { headers: { 'X-User': user } },
        ),
      );
      if (this.session.sheetId() === sid) this.claims.update((cs) => [...[...done.claims].reverse(), ...cs]);
      return done.added;
    } catch (e) {
      return failed('add', e).replace(' claim', ' claims');
    }
  }

  /** Change a DRAFT claim's amount, date and note; when refused, the reason and whether it is the
   *  claim itself that refused it (it is no longer a DRAFT) rather than the fields typed. */
  async update(id: number, f: ClaimFields): Promise<{ message: string; onClaim: boolean } | null> {
    const refused = this.check(f);
    if (refused) return { message: refused, onClaim: false };
    const sid = this.session.sheetId()!;
    try {
      const claim = await firstValueFrom(
        this.http.put<Claim>(`${this.url(sid)}/claims/${id}`, this.body(f), {
