89	/** DRAFT when added; DRAFT -> OPEN -> SETTLED, and DRAFT, OPEN or PENDING -> VOID. A clerk settling a
90	 *  due above the clerk limit makes it PENDING: a steward approves it (SETTLED) or rejects it (OPEN). A
91	 *  steward can re-settle a SETTLED claim at its figure today. A DRAFT can be deleted (DELETED, counting
92	 *  nowhere) and restored to DRAFT on the sheet's today it was deleted. */
93	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED';
94	
95	/** A status change a claim's buttons ask for. */
96	export type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject' | 'resettle' | 'delete' | 'restore';
97	
98	/** Whether a claim in this status counts toward claimed, due-total and every total. */
99	export function counts(c: Claim): boolean {
100	  return c.status === 'OPEN' || c.status === 'PENDING' || c.status === 'SETTLED';
101	}
102	
103	/** Whether a claim in this status counts toward the totals; no status (not yet added) does not. */
104	export function countsAt(status: ClaimStatus | null): boolean {
105	  return status === 'OPEN' || status === 'PENDING' || status === 'SETTLED';
106	}
107	
108	/** The status a claim had at the end of a day (YYYY-MM-DD), as its status log records it: its latest line
109	 *  dated on or before it; null when it was added after it. A claim with no log has its status now. */
110	export function statusAt(c: Claim, day: string): ClaimStatus | null {
111	  if (c.statusLog.length === 0) return c.status;
112	  let status: ClaimStatus | null = null;
113	  for (const l of c.statusLog) if (l.on <= day) status = l.status;
114	  return status;
115	}
116	
117	/** Whether a claim is still open (OPEN or PENDING): it goes overdue, and a hold over its date takes it
118	 *  out of the live totals unless a statement binds it. */
119	export function isOpen(c: Claim): boolean {
120	  return c.status === 'OPEN' || c.status === 'PENDING';
121	}
122	
123	/** Whether a claim is bound by its person's last statement now: a PENDING claim shows and totals its
124	 *  live figure until rejected back to OPEN. */
125	export function bound(c: Claim): boolean {
126	  return c.stated && c.status !== 'PENDING';
127	}
