133	  note: string;
134	  /** The number of the settled claim a negative amount corrects; blank for any other claim. */
135	  corrects: string;
136	  /** The external reference, surrounding spaces removed; blank for none. */
137	  ref: string;
138	  /** The tags, comma separated; blank for none. */
