142	// The people's claims on the active sheet, newest first, re-read from the server each time the
143	// sheet is loaded. Sums are kept in whole cents so they add up exactly, and count only OPEN, PENDING
144	// and SETTLED claims.
145	@Injectable({ providedIn: 'root' })
146	export class Claims {
147	  private readonly http = inject(HttpClient);
148	  private readonly session = inject(Session);
149	  private readonly people = inject(People);
150	
151	  readonly claims = signal<Claim[]>([]);
152	  /** The tags the sheet's claims have carried, as last read from the server. */
153	  private readonly storedTags = signal<string[]>([]);
154	  /** Every tag ever used on the sheet, sorted: those stored and those its claims carry now. */
155	  readonly usedTags = computed(() =>
156	    [...new Set([...this.storedTags(), ...this.claims().flatMap((c) => c.tags)])].sort(),
157	  );
158	  /** The ids of the claims chosen for a bulk action. */
159	  readonly selected = signal<ReadonlySet<number>>(new Set());
160	  private loads = 0;
161	
162	  /** The claims that count in the live totals: those that count, less the OPEN and PENDING claims bound
163	   *  by no statement and dated within one of their person's holds or whose person's retirement date is
164	   *  reached, and the deferred claims. */
165	  readonly live = computed(() => {
166	    const leftOut = this.leftOut();
167	    return this.claims().filter((c) => counts(c) && !leftOut(c) && !this.deferred(c));
168	  });
169	
170	  /** The claims a period's figures may count, whatever their status: all but the OPEN and PENDING claims
171	   *  bound by no statement and dated within one of their person's holds, and the deferred claims, as the
172	   *  live totals leave those out. */
173	  readonly periodCandidates = computed(() => {
174	    const leftOut = this.leftOut();
175	    return this.claims().filter((c) => !leftOut(c) && !this.deferred(c));
176	  });
177	
178	  /** Whether a hold or a retirement leaves a claim out of the live totals: it is OPEN or PENDING, bound
179	   *  by no statement, and dated within one of its person's holds or its person's retirement date is
180	   *  reached on the sheet's today. */
181	  private readonly leftOut = computed(() => {
182	    const today = this.session.today();
183	    const byId = new Map(this.people.people().map((p) => [p.id, p]));
184	    return (c: Claim): boolean => {
185	      const p = byId.get(c.personId);
186	      return isOpen(c) && !bound(c) && p !== undefined
187	        && (heldOn(p.holds, c.date) || retiredBy(p, today));
188	    };
189	  });
190	
191	  /** The claims that count toward claimed: the live ones, leaving out claims that correct another. */
192	  private readonly counted = computed(() => this.live().filter((c) => !c.corrects));
193	
194	  /** Each person's claimed, in cents, by person id. */
195	  readonly claimedCents = computed(() => {
196	    const out = new Map<number, number>();
197	    for (const c of this.counted()) out.set(c.personId, (out.get(c.personId) ?? 0) + cents(c.amount));
198	    return out;
199	  });
200	
201	  /** Everyone's claimed added up, with two decimals. */
202	  readonly total = computed(() => money(this.counted().reduce((sum, c) => sum + cents(c.amount), 0)));
203	
204	  /** The date a claim is due by: fixed when it was added, from the terms of its person's grade then. */
205	  dueBy(c: Claim): string {
206	    return c.dueBy;
207	  }
208	
209	  /** The date a claim's lateness runs from: its due-by plus the grace days in force on its date of its
210	   *  person's grade in force then (none: the due-by). */
211	  lateFrom(c: Claim): string {
212	    const p = this.people.people().find((x) => x.id === c.personId);
213	    const grace = p === undefined ? 0 : this.session.graceOn(gradeOn(p.grades, c.date), c.date);
214	    return grace === 0 ? this.dueBy(c) : addDays(this.dueBy(c), grace);
215	  }
216	
217	  /** Whether a claim is overdue: OPEN or PENDING, not deferred, with its due-by plus its grace (see
218	   *  lateFrom) before the sheet's today. */
219	  overdue(c: Claim): boolean {
220	    const today = this.session.today();
221	    return isOpen(c) && !this.deferred(c) && today !== null && this.lateFrom(c) < today;
222	  }
223	
224	  /** Whether a claim shows as deferred: its deferred-until date is after the sheet's today, whatever its
225	   *  status (a deferred claim voided keeps showing it). Only an OPEN one is left out of totals (`deferred`). */
226	  deferredShown(c: Claim): boolean {
227	    const today = this.session.today();
228	    return c.deferredUntil !== null && today !== null && today < c.deferredUntil;
229	  }
230	
231	  /** Whether a claim is deferred: OPEN, with a deferred-until date after the sheet's today. Until then it
232	   *  counts in no total, is not overdue and cannot be settled. */
233	  deferred(c: Claim): boolean {
234	    const today = this.session.today();
235	    return c.status === 'OPEN' && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
236	  }
237	
238	  /** The late charge, in cents, on a claim's figure (in cents): while it is overdue, for each full 30 days
239	   *  past its due-by plus its grace (see lateFrom), the sheet's late percent in force on that boundary date
240	   *  (that date plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries before it, rounded to cents as its date rounds, the charges added up; none otherwise, and none
241	   *  on a correction. Never bound by a statement; frozen into the due when settled. */
242	  lateCents(c: Claim, figureCents: bigint): bigint {
243	    const today = this.session.today();
244	    if (!this.overdue(c) || today === null || c.amount.startsWith('-')) return 0n;
245	    const from = this.lateFrom(c);
246	    const periods = Math.floor(daysBetween(from, today) / 30);
247	    const halfUp = this.session.roundsHalfUp(c.date);
248	    let total = 0n;
249	    for (let k = 1; k <= periods; k++) {
250	      total += rounded((figureCents + total) * hundredths(this.session.latePctOn(addDays(from, 30 * k))), 10000n, halfUp);
251	    }
252	    return total;
253	  }
254	
255	  /** A claim's due from its figure (the rate figure, or the one its statement bound), in cents: the figure
256	   *  with its late charge on top, at least the sheet's floor in force on the claim's date (the floor applied
257	   *  last); a correction takes neither charge nor floor. */
258	  chargedCents(c: Claim, figureCents: bigint): bigint {
259	    if (c.amount.startsWith('-')) return figureCents;
260	    const due = figureCents + this.lateCents(c, figureCents);
261	    const floor = hundredths(this.session.floorOn(c.date));
262	    return due < floor ? floor : due;
263	  }
264	
265	  /** The date a claim's figures round by: its own, or for a correction the date of the claim of the same
266	   *  person it corrects (its own when that is not found). */
267	  roundingDate(c: Claim): string {
268	    if (c.corrects === null) return c.date;
269	    return this.claims().find((o) => o.personId === c.personId && o.number === c.corrects)?.date ?? c.date;
270	  }
271	
272	  /** A person's claims, newest first. */
273	  of(personId: number): Claim[] {
274	    return this.claims().filter((c) => c.personId === personId);
275	  }
276	
277	  /** A person's claimed, with two decimals. */
278	  claimed(personId: number): string {
279	    return money(this.claimedCents().get(personId) ?? 0);
280	  }
281	
282	  /** Replace a person's claims with these, as the server answered them (newest first). */
283	  replaceOf(personId: number, theirs: Claim[]): void {
284	    const byId = new Map(theirs.map((c) => [c.id, c]));
285	    this.claims.update((cs) => cs.map((c) => (c.personId === personId ? (byId.get(c.id) ?? c) : c)));
286	  }
