288	  /** Re-read the active sheet's claims from the server; an error message when that failed. */
289	  async load(): Promise<string | null> {
290	    const user = this.session.user();
291	    const sid = this.session.sheetId();
292	    const load = ++this.loads;
293	    this.claims.set([]);
294	    this.storedTags.set([]);
295	    this.selected.set(new Set());
296	    if (!user || !sid) return null;
297	    try {
298	      const [claims, tags] = await Promise.all([
299	        firstValueFrom(this.http.get<Claim[]>(`${this.url(sid)}/claims`, { headers: { 'X-User': user } })),
300	        firstValueFrom(this.http.get<string[]>(`${this.url(sid)}/claim-tags`, { headers: { 'X-User': user } })),
301	      ]);
302	      if (load === this.loads) {
303	        this.claims.set(claims);
304	        this.storedTags.set(tags);
305	      }
306	      return null;
307	    } catch (e) {
308	      return failed('load', e).replace(' claim', ' claims');
309	    }
310	  }
