349	  /** Quick-add a DRAFT claim dated the sheet's today, with an empty note, for the person with the
350	   *  name, the server adding them with grade A first when the sheet has no one by it; an error
351	   *  message when refused. */
352	  async quickAdd(name: string, amount: string): Promise<string | null> {
