403	  /** Change a DRAFT claim's amount, date and note; when refused, the reason and whether it is the
404	   *  claim itself that refused it (it is no longer a DRAFT) rather than the fields typed. */
405	  async update(id: number, f: ClaimFields): Promise<{ message: string; onClaim: boolean } | null> {
406	    const refused = this.check(f);
407	    if (refused) return { message: refused, onClaim: false };
408	    const sid = this.session.sheetId()!;
409	    try {
410	      const claim = await firstValueFrom(
411	        this.http.put<Claim>(`${this.url(sid)}/claims/${id}`, this.body(f), {
412	          headers: { 'X-User': this.session.user()! },
413	        }),
414	      );
415	      if (this.session.sheetId() === sid) {
416	        // a tag the edit took off stays among those used on the sheet
417	        const was = this.claims().find((c) => c.id === id)?.tags ?? [];
418	        this.storedTags.update((ts) => [...new Set([...ts, ...was])]);
419	        this.claims.update((cs) => cs.map((c) => (c.id === id ? claim : c)));
420	      }
421	      return null;
422	    } catch (e) {
423	      if (e instanceof HttpErrorResponse && e.status === 409) {
424	        return { message: message(e) ?? 'Only a DRAFT claim can be edited.', onClaim: !onForm(e) };
425	      }
426	      return { message: failed('save', e), onClaim: false };
427	    }
428	  }
