/** A member of a pool with its share percent: a person (personId), or another pool (poolId). A retired
 *  person counts their share toward the pool's total but is left out of its cuts. */
export interface PoolMemberView {
  personId: number | null;
  poolId: number | null;
  name: string;
  share: string;
  retired: boolean;
  /** Their cut of the pool's pot, two decimals (0.00 when retired or on hold on the sheet's today, their
   *  share spread over the others with a cut); null when the pool is unbalanced,
   *  has no pot, or every member is retired. A pool in another has its cut there as its pot; one in none has the sheet's pot. */
  cut: string | null;
  /** The membership's first and last day, YYYY-MM-DD; null when open-ended. */
  from: string | null;
  to: string | null;
  /** Whether its dates include the sheet's today; one that is not is left out of the pool entirely. */
  active: boolean;
}

  private readonly session = inject(Session);

  /** In the order they were added. */
  readonly pools = signal<PoolView[]>([]);
  private loads = 0;

  /** Each person's cuts across every pool they are a member of, added up, in hundredths, by person id; a pool
   *  that shows no cuts adds nothing. */
  readonly cutCents = computed(() => {
    const out = new Map<number, bigint>();
    for (const pool of this.pools()) {
      for (const m of pool.members) {
        if (m.personId !== null && m.cut !== null) {
          out.set(m.personId, (out.get(m.personId) ?? 0n) + hundredths(m.cut));
        }
      }
  /** The grade in force on the sheet's today when the server answered. */
  grade: string;
  /** Every grade they were given, the first (no from-date) first, then by from-date. */
  grades: GradeFrom[];
  /** Moved on by each save; an edit made from an older version is refused. */
  version: number;
  /** How many statements were taken of them. */
  statementCount: number;
  /** The last statement's due-total, two decimals or n/a; null before their first. */
  statedTotal: string | null;
  /** The last statement's date: the sheet's today when it was taken, or the date it was taken as of; null
   *  before their first. */
  statementDate: string | null;
  /** Whether a retirement date is set: then they count as retired at once, whatever the date. */
  retired: boolean;
  /** The date they are retired from (YYYY-MM-DD); null while not retired. */
  retiredFrom: string | null;
  /** Their past retirements, by from-date. */
  retirements: Retirement[];
  /** Whether they have any hold at all. */
  held: boolean;
  /** Their holds, by from-date: an OPEN or PENDING claim dated within one, and bound by no statement,
   *  counts in no live total. */
  holds: Hold[];
  /** The ids of the other people on the sheet they have named as their patrons. */
  patronIds: number[];
  /** Whether the signed-in user watches them. */
  watched: boolean;
  /** Their own terms in days, ahead of their grade's and the sheet's; null when they have none. */
  terms: number | null;
  /** Their contact, trimmed and lower-cased; null when they have none. */
  contact: string | null;
  /** The other names they go by, sorted as names are compared: without regard to case. */
  aliases: string[];
  /** Whether their name or an alias is used on another sheet of the sheet's tree: every save of the person
   *  form is refused until a rename leaves them clashing with no one. */
  clashing: boolean;
  /** The sheet they were transferred from; null for anyone added on this sheet. */
  origin: string | null;
  /** Their tags: trimmed, lower-cased, without repeats, sorted; empty when they carry none. */
  tags: string[];
